"""Differential test: fast nesting scanner vs a naive per-character reference."""
import json, random, sys
sys.path.insert(0, '/workspace/submission')
import main as M

def reference_depth_within(raw):
    depth, instr, esc, seen_bad = 0, False, False, False
    for byte in raw:
        if instr:
            if esc:
                esc = False
            elif byte == 0x5C:
                esc = True
            elif byte == 0x22:
                instr = False
            continue
        if byte == 0x22:
            instr = True
        elif byte in (0x5B, 0x7B):
            depth += 1
            if depth > M.MAX_DEPTH:
                return False
        elif byte in (0x5D, 0x7D):
            depth -= 1
            if depth < 0:
                return False
    return not instr and not esc

rng = random.Random(4242)
POOL = ['"', '\\', '[', ']', '{', '}', ' ', '\\"', '\\\\', '\\n', '\\t', '\\u0041',
        '\\u005d', '\\u0022', 'a', 'z', '0', '-', '_', '.', 'x' * 20]
payloads = []
for _ in range(20000):
    n = rng.randint(0, 40)
    s = ''.join(rng.choice(POOL) for _ in range(n))
    if rng.random() < 0.3:
        s += '"' + s + '"'
    payloads.append(s)
mismatch = 0
for s in payloads:
    raw = s.encode()
    a = M.nesting_within_limit(raw)
    b = reference_depth_within(raw)
    if a != b:
        mismatch += 1
        if mismatch < 6:
            print('MISMATCH fast=%r ref=%r for %r' % (a, b, s[:80]))
print('scanner differential: %d mismatches out of %d' % (mismatch, len(payloads)))

# Now with well-formed JSON documents built out of nasty strings.
def rnd_string(rng, limit=300):
    out = []
    while sum(len(x) for x in out) < limit:
        out.append(rng.choice(['"', '\\\\', '\\n', '\\u0022', '\\u005b', '\\u007b',
                               'q', '[[', ']]', '{{', '}}', ' ', '\\t', '\\/']))
    return ''.join(out)

bad = 0
for i in range(4000):
    txt = rnd_string(rng)
    if '"' in txt.replace('\\"', '').replace('\\u0022', ''):
        txt = txt.replace('"', '')
    doc = {'zones': [{'origin': '.', 'records': [
        {'owner': 'a.', 'type': 'TXT', 'data': txt[:256]}]}],
           'profiles': [{'id': 'p', 'max_aliases': 4, 'cname': 'follow', 'wildcard': 'rfc'}],
           'queries': [], 'observations': []}
    raw = json.dumps(doc).encode()
    if not M.nesting_within_limit(raw) and reference_depth_within(raw):
        bad += 1
        if bad < 4:
            print('FALSE REJECT: %r' % txt[:100])
    # the whole program must accept every such document
    if i % 400 == 0:
        import subprocess
        p = subprocess.run([sys.executable, '-I', '/workspace/submission/main.py'],
                           input=raw, capture_output=True)
        if not p.stdout.startswith(b'{"runs":'):
            print('PROGRAM REJECTED valid nasty doc:', p.stdout[:80], txt[:60])
            bad += 1
print('nasty-json document scan: %d problems' % bad)
# depth-limit equivalence on crafted bracket nesting
for depth in (30, 31, 32, 33, 40, 100):
    raw = ('{"zones":' + '[' * depth + ']' * depth + ',"profiles":[],"queries":[],"observations":[]}').encode()
    a, b = M.nesting_within_limit(raw), reference_depth_within(raw)
    ok = (depth <= 32) == a and a == b
    print('depth %-4d fast=%-5s ref=%-5s %s' % (depth, a, b, 'ok' if ok else 'MISMATCH'))
PYEOF
